import sys, os, re, argparse, fnmatch

VERSION = "0.1"

DEFAULT_PATTERNS = [
    re.compile(r"-----BEGIN (?:RSA )?PRIVATE KEY-----"),
    re.compile(r"ssh-(?:rsa|dss|ed25519) "),
    re.compile(r"(?i)password\s*[=:]\s*[^\s']+"),
    re.compile(r"(?i)passwd\s*[=:]\s*[^\s']+"),
    re.compile(r"(?i)api[_-]?key\s*[=:]\s*[^\s']{8,}"),
    re.compile(r"(?i)secret\s*[=:]\s*[^\s']{8,}"),
    re.compile(r"AKIA[0-9A-Z]{16}"),
    re.compile(r"(?i)token\s*[=:]\s*[^\s']{8,}"),
    re.compile(r"[A-Za-z0-9+/]{40,}={0,2}"),
]

IGNOREFILES = ['.git', '.hg']


def load_secretsignore(path='.secretsignore'):
    patterns = []
    exact_secrets = set()
    if not os.path.exists(path):
        return patterns, exact_secrets
    section = None
    with open(path, 'r', encoding='utf-8', errors='ignore') as f:
        for raw in f:
            line = raw.rstrip('\n')
            s = line.strip()
            if not s or s.startswith('#'):
                continue
            if s.startswith('[') and s.endswith(']'):
                section = s[1:-1].strip()
                continue
            if section == 'secrets':
                exact_secrets.add(line)
            else:
                patterns.append(line)
    return patterns, exact_secrets


def matches_ignore(path, patterns):
    # patterns are gitignore-style globs relative to cwd
    rel = os.path.relpath(path, os.getcwd())
    for pat in patterns:
        # treat patterns starting with / as relative to repo root
        p = pat
        if p.startswith('/'):
            p = p[1:]
        # use fnmatch for glob
        if fnmatch.fnmatch(rel, p) or fnmatch.fnmatch(os.path.basename(rel), p):
            return True
    return False


def is_text_file(path):
    try:
        with open(path, 'rb') as f:
            chunk = f.read(4096)
            if b"\0" in chunk:
                return False
            # crude heuristic: if many non-printable bytes, treat as binary
            text_chars = bytearray({7,8,9,10,12,13,27} | set(range(0x20,0x100)))
            nontext = sum(1 for b in chunk if b not in text_chars)
            return (nontext / max(1, len(chunk))) < 0.30
    except Exception:
        return False


def scan_file(path, regexes, exact_secrets):
    findings = []
    try:
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            for i, line in enumerate(f, start=1):
                for r in regexes:
                    m = r.search(line)
                    if m:
                        val = m.group(0)
                        if val in exact_secrets:
                            continue
                        findings.append((path, i, line.rstrip('\n')))
                        break
    except Exception:
        pass
    return findings


def collect_targets(args_paths):
    targets = []
    if not args_paths:
        args_paths = ['.']
    for p in args_paths:
        if os.path.isdir(p):
            for root, dirs, files in os.walk(p):
                # skip VCS dirs
                dirs[:] = [d for d in dirs if d not in IGNOREFILES]
                for fname in files:
                    fpath = os.path.join(root, fname)
                    targets.append(fpath)
        else:
            targets.append(p)
    return targets


def main():
    parser = argparse.ArgumentParser(prog='ripsecrets', description='ripsecrets - detect potential secrets in source files')
    parser.add_argument('paths', nargs='*', help='Files or directories to scan')
    parser.add_argument('--additional-pattern', '-p', action='append', help='Additional regex pattern to search for', default=[])
    parser.add_argument('--version', action='store_true', help='Show version')
    args = parser.parse_args()

    if args.version:
        print('ripsecrets', VERSION)
        return 0

    ignore_patterns, exact_secrets = load_secretsignore()

    regexes = DEFAULT_PATTERNS[:]
    for pat in args.additional_pattern:
        try:
            regexes.append(re.compile(pat))
        except re.error:
            # treat as glob-like string: search literal
            regexes.append(re.compile(re.escape(pat)))

    targets = collect_targets(args.paths)

    any_findings = False
    for t in targets:
        if matches_ignore(t, ignore_patterns):
            continue
        if os.path.isdir(t):
            continue
        if not is_text_file(t):
            continue
        findings = scan_file(t, regexes, exact_secrets)
        for path, lineno, content in findings:
            print(f"{path}:{lineno}:{content}")
            any_findings = True

    if any_findings:
        return 1
    return 0

if __name__ == '__main__':
    sys.exit(main())
